struct Node;

// Convert a count of days since the Unix epoch (1970-01-01) into a
// proleptic-Gregorian (year, month, day). Based on Howard Hinnant's
// civil-from-days algorithm.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as i64; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32; // [1, 12]
    let year = if m <= 2 { y + 1 } else { y };
    (year, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // The node's entire authority is the wall clock; read it once.
        let now = crate::wasi::clocks::wall_clock::now();
        let seconds = now.seconds;

        // Derive a calendar date from the clock reading.
        let days = (seconds / 86_400) as i64;
        let (year, month, day) = civil_from_days(days);

        // ensures len(date) == 10 : "YYYY-MM-DD".
        // Clamp the year to the 4-digit range so the length is exactly 10.
        let year = year.clamp(0, 9999);
        let date = format!("{:04}-{:02}-{:02}", year, month, day);

        RunInfo {
            date,          // length == 10 by construction
            started: seconds, // u64, so started >= 0 holds
        }
    }
}

export!(Node);
